function create(){({reports:reportForm,campaigns:campaignForm,articles:articleForm,users:editUser,blacklist:editBlacklist,configs:configForm}[page.value])?.()}
const d=computed(()=>detail.value?.data||{})
const primaryRoute=computed(()=>({CENTER:'alerts',PAYMENT:'commands',GRID:'visits',PUBLIC:'reports'}[role.value]))
const dashboardColumns=computed(()=>role.value==='CENTER'?[{key:'code',label:'预警编号'},{key:'level',label:'风险',badge:true},{key:'score',label:'评分'},{key:'state',label:'办理状态',badge:true}]:[{key:'code',label:'业务编号'},{key:'state',label:'当前状态',badge:true},{key:'created_at',label:'创建时间'}])
const detailPairs=computed(()=>{const fields={code:'业务编号',kind:'业务类型',state:'当前状态',processing:'研判状态',level:'风险等级',score:'规则评分',created_at:'创建时间',expires_at:'到期时间',person:'服务对象',phone:'联络号码',arrived_at:'到场时间',result:'办理结果',returned_at:'回传时间',requested:'指令金额',actual:'实际执行',remaining:'剩余冻结',returned:'累计返还',reserved:'待执行占用',amount:'申请金额',approved:'核定金额',extension_count:'延期次数',value:'举报线索',transactionTime:'交易时刻',updated_at:'更新时间'};return Object.entries(fields).filter(([key])=>d.value[key]!=null).map(([key,label])=>({label,value:['requested','actual','remaining','returned','reserved','amount','approved'].includes(key)?money(d.value[key]):fmt(d.value[key])}))})
</script>

<template>
 <div v-if="!session.ready" class="initial-loading">正在连接反诈协同处置平台…</div>
 <div v-else-if="!user&&page==='welcome'" class="welcome">
  <div class="welcome-top"><a href="#welcome" class="brand dark"><svg viewBox="0 0 32 36" aria-hidden="true"><path d="M16 2 29 7v10c0 8-7 14-13 17C10 31 3 25 3 17V7Z"/><path class="shield-tick" d="m10 17 4 4 8-9"/></svg><span>反诈协同处置平台<small>守护，从一次及时响应开始</small></span></a><div class="public-nav"><button @click="go('articles')">反诈知识</button><button @click="go('lookup')">举报进度查询</button><button class="primary" @click="reportForm">匿名举报 →</button></div></div>
  <main class="welcome-main"><section class="welcome-story"><span class="eyebrow">协同防范 · 及时处置</span><h1>让线索得到回应，<br>让守护形成合力。</h1><p>连接群众、反诈中心、支付机构与社区网格。<br>从线索受理到协同处置，每一步都清晰可查。</p><div class="flow-art" aria-label="群众举报，中心研判，机构与社区协同，结果反馈"><div class="flow-node"><span>01</span><strong>发现线索</strong><small>群众举报</small></div><div class="flow-connector">→</div><div class="flow-node active"><span>02</span><strong>核实研判</strong><small>反诈中心</small></div><div class="flow-connector">→</div><div class="flow-node"><span>03</span><strong>协同守护</strong><small>机构与社区</small></div></div><div class="welcome-note"><span class="status-dot"></span>课程原型 · 本地运行 · 模拟业务资料</div></section><section class="login-card"><p class="eyebrow">工作台登录</p><h2>欢迎回来</h2><p class="muted">使用分配的账号进入对应业务平台。</p><form @submit.prevent="login"><label class="field"><span>账号</span><input v-model="username" required autocomplete="username" placeholder="请输入账号"></label><label class="field"><span>密码</span><input v-model="password" required type="password" autocomplete="current-password" placeholder="请输入密码"></label><div v-if="error" class="error-box" role="alert">{{error}}</div><button class="primary login-submit" :disabled="loginBusy">{{loginBusy?'登录中…':'进入工作台 →'}}</button></form><details class="demo-help"><summary>查看课程演示账号</summary><p>演示密码：<code>Demo2026!</code></p><div class="demo-accounts"><button v-for="a in [{id:'center',label:'反诈中心'},{id:'public1',label:'群众服务'},{id:'pay1',label:'支付机构'},{id:'grid1',label:'社区网格'}]" @click="demo(a.id)">{{a.label}} · {{a.id}}</button></div></details><div class="login-bottom">匿名举报无需登录，受理后请保存查询凭证。</div></section></main><footer class="welcome-footer"><span>反诈协同处置平台</span><span>所有资金操作均为模拟执行</span></footer>
 </div>
 <div v-else class="workspace">
  <aside :class="['sidebar',{open:mobile}]"><a href="#dashboard" class="brand"><svg viewBox="0 0 32 36" aria-hidden="true"><path d="M16 2 29 7v10c0 8-7 14-13 17C10 31 3 25 3 17V7Z"/><path class="shield-tick" d="m10 17 4 4 8-9"/></svg><span>反诈协同<small>协同处置平台</small></span></a><div class="workspace-tag">{{roleNames[role]||'公共服务'}}</div><nav><p class="nav-section">业务工作台</p><button v-for="m in user?menus:[{id:'articles',label:'反诈知识',mark:'▣'},{id:'lookup',label:'举报查询',mark:'⌕'}]" :key="m.id" :class="{active:page===m.id}" @click="go(m.id)"><span class="nav-mark" aria-hidden="true">{{m.mark}}</span>{{m.label}}<span v-if="page===m.id" class="nav-active-dot"></span></button></nav><div class="sidebar-footer"><div class="avatar">{{user?.displayName?.slice(0,1)||'访'}}</div><div><strong>{{user?.displayName||'访客'}}</strong><small>{{user?.username||'无需登录即可举报'}}</small></div><button v-if="user" class="logout" aria-label="退出登录" @click="logout">↪</button><button v-else class="logout" @click="go('welcome')">登录</button></div></aside>
  <div v-if="mobile" class="nav-shade" @click="mobile=false"></div>
  <div class="main-area"><header class="topbar"><div><button class="mobile-menu" aria-label="打开菜单" @click="mobile=!mobile">☰</button><span class="muted">协同工作台</span><span class="breadcrumb">/</span><strong>{{title}}</strong></div><span class="demo-tag"><span class="status-dot"></span>本地演示 · 模拟数据</span></header>
  <main class="content"><div class="page-heading"><div><p class="eyebrow">{{new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}}</p><h1>{{title}}</h1><p>{{descriptions[page]}}</p></div><div class="heading-actions"><button v-if="user" :disabled="busy" @click="refresh">↻ 刷新</button><button v-if="canCreate" class="primary" @click="create">＋ {{page==='configs'?'发布新版本':page==='reports'?'提交线索':'新建'}}</button><button v-if="!user" class="primary" @click="reportForm">提交匿名举报</button></div></div>
   <div v-if="error" class="error-box page-error" role="alert">{{error}}<button class="text-button" @click="refresh">重试</button></div><div v-if="busy" class="loading-bar" aria-label="正在加载"></div>
   <template v-if="page==='dashboard'"><div v-if="role==='PUBLIC'" class="action-strip"><div><strong>{{user.displayName}} · 个人演示资料</strong><span>{{user.verified?'已完成演示实名关联，可申请返还与申诉':'尚未关联演示身份，请联系中心管理员核验'}}</span></div><span class="badge">{{user.verified?'已关联':'待核验'}}</span></div><section class="overview-banner"><div><span class="eyebrow">{{roleNames[role]}} · 办理概况</span><h2>{{role==='PUBLIC'?'您的每一次提交，都有迹可循。':role==='GRID'?'把及时的提醒，送到居民身边。':role==='PAYMENT'?'独立核查，准确执行。':'从发现风险，到协同守护。'}}</h2><p>{{role==='CENTER'?'优先关注高风险线索、异常反馈与临期指令。':'查看您的待办与办理进展，及时完成下一步。'}}</p></div><button @click="role==='PUBLIC'?reportForm():go(primaryRoute)">{{role==='PUBLIC'?'我要举报':'进入待办'}} <span>→</span></button><div class="banner-art" aria-hidden="true"><span></span><span></span><span></span></div></section>
    <div class="stats-filter"><span>统计范围</span><input type="date" v-model="from" aria-label="统计开始日期"><span>至</span><input type="date" v-model="to" aria-label="统计结束日期"><button class="small" @click="refresh">应用</button><a :href="exportUrl" class="export-link">↓ 导出汇总</a></div>
    <section class="metric-grid"><article v-for="m in stats.metrics" :key="m.label" class="metric-card" :class="m.tone"><div><span>{{m.label}}</span><span class="metric-icon">{{m.unit==='元'?'¥':m.unit==='%'?'↗':'▤'}}</span></div><strong>{{fmt(m.value)}}<small>{{m.unit}}</small></strong><p>按当前身份与日期范围统计</p></article></section>
    <section v-if="stats.byKind?.length" class="panel summary-breakdown"><h3>指令分类与有效回执</h3><div class="weight-row"><div v-for="k in stats.byKind"><strong>{{k.value}}<small> 条</small></strong><span>{{k.label}} · 申请 {{money(k.requested)}} · 实际 {{money(k.actual)}}</span></div></div><p class="muted">{{(stats.byResult||[]).map(r=>r.label+' '+r.value+'条').join(' · ')}}</p></section>
    <section class="dashboard-grid"><article class="panel"><div class="panel-heading"><div><h3>业务受理趋势</h3><p>按日期汇总实际业务记录</p></div><span class="tag">实时业务数据</span></div><div v-if="stats.daily.length" class="bar-chart"><div v-for="point in stats.daily.slice(-14)" class="bar-column" :title="point.day+'：'+point.value+'条'"><span>{{point.value}}</span><div :style="{height:Math.max(4,point.value/Math.max(...stats.daily.map(d=>d.value))*120)+'px'}"></div><small>{{point.day.slice(5)}}</small></div></div><div v-else class="empty compact">当前日期范围内暂无业务记录</div></article><article class="panel"><div class="panel-heading"><h3>{{isCenter?'风险分布':'办理提示'}}</h3></div><div v-if="isCenter" class="risk-list"><div v-for="level in ['高','中','低']"><span class="badge" :class="statusTone(level)">{{level}}风险</span><div class="risk-track"><i :class="statusTone(level)" :style="{width:(stats.risks.find(r=>r.label===level)?.value||0)/Math.max(1,stats.risks.reduce((a,r)=>a+Number(r.value),0))*100+'%'}"></i></div><strong>{{stats.risks.find(r=>r.label===level)?.value||0}}</strong></div><p class="muted">等级由规则辅助判断，派发前须经人工核实。</p></div><div v-else class="tips"><p><span>01</span>核对单据与资料，确认当前身份及办理范围。</p><p><span>02</span>如实记录结果，失败与部分执行也须留痕。</p><p><span>03</span>保存后可在详情中查看进度与相关记录。</p></div></article></section>
    <section class="panel"><div class="panel-heading"><div><h3>{{role==='PUBLIC'?'最近提交':'重点关注'}}</h3><p>查看业务状态，继续下一步办理</p></div><button class="text-button" @click="go(primaryRoute)">查看全部 →</button></div><DataTable :rows="rows.slice(0,10)" :columns="dashboardColumns" @select="openDetail(primaryRoute,$event)"/></section>
   </template>
   <section v-else-if="page==='lookup'" class="panel lookup-panel"><div class="panel-heading"><div><h3>凭受理凭证查询</h3><p>仅返回这条举报的办理摘要，请妥善保管凭证。</p></div></div><form @submit.prevent="query"><label class="field"><span>受理编号</span><input v-model="queryCode" required placeholder="请输入JB开头的受理编号"></label><label class="field"><span>查询凭证</span><input v-model="queryToken" required type="password" placeholder="请输入提交后保存的查询凭证"></label><button class="primary">查询进度</button></form><dl v-if="queryResult" class="details-grid"><template v-for="(label,key) in {code:'受理编号',processing:'研判状态',state:'办理状态',created_at:'受理时间',updated_at:'更新时间'}"><dt>{{label}}</dt><dd>{{fmt(queryResult[key])}}</dd></template></dl></section>
   <section v-else-if="page==='articles'" class="article-grid"><article v-for="a in rows" :key="a.id" class="article-card"><div class="article-cover"><span>{{a.category}}</span><svg viewBox="0 0 64 64" aria-hidden="true"><path d="M32 8 52 16v15c0 13-10 22-20 27C22 53 12 44 12 31V16Z"/><path d="m23 31 6 6 13-15"/></svg></div><div><span class="badge" :class="statusTone(a.state)">{{a.state}}</span><h3>{{a.title}}</h3><p>{{a.summary}}</p><button class="text-button" @click="openDetail('articles',a)">阅读详情 →</button></div></article><div v-if="!rows.length" class="panel empty">暂无已发布文章</div></section>
   <section v-else-if="page==='configs'" class="panel"><div class="panel-heading"><div><h3>规则版本历史</h3><p>默认采用五因子加权，权重总和为100。</p></div></div><article v-for="c in rows" class="config-version"><header><h3>版本 {{c.id}}</h3><span class="muted">{{fmt(c.created_at)}} · {{c.display_name}}</span></header><div class="weight-row"><div v-for="(w,i) in c.data.weights"><strong>{{w}}<small>%</small></strong><span>{{['金额','时段','异地','黑名单','异常行为'][i]}}</span></div></div><div class="config-summary">高风险 ≥ {{c.data.high}} · 中风险 ≥ {{c.data.medium}} · 归并 {{c.data.mergeHours}} 小时 · 冻结 {{c.data.freezeHours}} 小时 · 最多延期 {{c.data.maxExtensions}} 次 · 机构超时 {{c.data.timeoutMinutes}} 分钟</div></article></section>
   <template v-else-if="page==='applications'"><div v-if="role==='PUBLIC'" class="action-strip"><div><strong>后续办理</strong><span>需完成演示实名并关联本人有效止付</span></div><button @click="applicationForm('返还')">申请资金返还</button><button class="primary" @click="applicationForm('申诉')">提交误冻结申诉</button></div><section class="panel"><DataTable :key="page" :server="pagination" :resource="page" @query="listChanged" :columns="columns" :rows="rows" @select="select"/></section></template>
   <section v-else-if="columns.length" class="panel"><DataTable :key="page" :server="pagination" :resource="page" @query="listChanged" :columns="columns" :rows="rows" :selectable="!['banks','logs'].includes(page)" @select="select"/></section>
  </main><footer class="workspace-footer"><span>反诈协同处置平台 · 课程原型</span><span>业务数据持久保存 · 外部资金操作模拟</span></footer></div>
 </div>

 <div v-if="detail" class="drawer-backdrop" @click.self="detail=null"><section class="detail-drawer" role="dialog" aria-modal="true" aria-label="业务详情"><header class="drawer-header"><div><p class="eyebrow">{{({alerts:'研判详情',reports:'举报详情',commands:'指令详情',visits:'任务详情',applications:'申请详情',articles:'知识文章',campaigns:'宣防详情',notices:'督办详情',corrections:'更正详情'})[detail.type]}}</p><h2>{{d.title||d.code||'办理记录'}}</h2></div><button class="icon-button" aria-label="关闭详情" @click="detail=null">×</button></header><div class="drawer-body">
  <div v-if="error" class="error-box" role="alert">{{error}}</div>
  <div class="detail-actions">
   <template v-if="detail.type==='alerts'"><button v-if="isCenter&&!['已闭环','已驳回','已作废'].includes(d.state)" @click="form('作废预警及未执行任务',[note('作废原因')],`/alerts/${d.id}/void`,{},'仅允许机构未受理、网格未到场的记录作废；所有原始材料和日志继续保留。')">作废</button><button v-if="!['已闭环','已驳回','已作废'].includes(d.state)" class="primary" @click="reviewForm(d)">人工复核 / 补录</button><button v-if="['已核实','已派单','处置中'].includes(d.state)&&!d.needs_review" @click="dispatchForm(d)">联动派发</button><button v-if="['已派单','处置中'].includes(d.state)" @click="form('确认本轮办结',[note('办结意见与异常处理决定')],`/alerts/${d.id}/close`)">确认办结</button></template>
   <template v-if="detail.type==='commands'"><button v-if="role==='PAYMENT'&&d.state==='已送达'" class="primary" @click="action(`/commands/${d.id}/accept`)">受理指令</button><button v-if="role==='PAYMENT'&&d.state==='受理中'" class="primary" @click="receiptForm(d)">核查后提交回执</button><button v-if="role==='PAYMENT'&&d.receipts?.length" @click="correctionForm(d)">申请更正</button><button v-if="isCenter&&d.kind==='止付'&&['生效中','已延期'].includes(d.state)" @click="form('申请延期',[note('延期理由')],`/commands/${d.id}/extend`)">延期</button><button v-if="isCenter&&['未处理','拒绝执行','已拒绝'].includes(d.state)" @click="form('核实后重发',[note('重新核实意见与重发理由')],`/commands/${d.id}/retry`)">复核重发</button><button v-if="isAdmin&&['生效中','已延期','已送达','受理中'].includes(d.state)" @click="form('演示时效节点',[f('node','检查节点','select',{required:true,options:['已送达','受理中'].includes(d.state)?['超时']:['24小时','2小时','到期']})],`/commands/${d.id}/simulate`,{},'只推动当前模拟指令到选定节点；到期会真实更新模拟账本，并记录演示标识。')">演示时效</button></template>
   <template v-if="detail.type==='visits'"><button v-if="role==='GRID'&&d.state==='待接收'" class="primary" @click="action(`/visits/${d.id}/claim`)">接收任务</button><button v-if="isCenter&&['待接收','待上门'].includes(d.state)" @click="form('改派网格任务',[f('assigneeId','本社区执行人','select',{required:true,options:option((meta.gridUsers||[]).filter(g=>g.community_id===d.community_id),'id','display_name')}),note('改派原因')],`/visits/${d.id}/assign`)">指定 / 改派</button><button v-if="role==='GRID'&&d.assignee_id===user.id&&d.state==='待上门'" class="primary" @click="arriveForm(d)">记录到场</button><button v-if="role==='GRID'&&d.assignee_id===user.id&&d.state==='劝阻中'" class="primary" @click="feedbackForm(d)">回传结果</button><button v-if="['已回传','已归档'].includes(d.state)&&(isCenter||d.assignee_id===user.id)" @click="form('追加说明',[note()],`/visits/${d.id}/append`)">追加说明</button></template>
   <template v-if="detail.type==='applications'"><button v-if="isCenter&&['待核定','待受理','审核中'].includes(d.state)" class="primary" @click="applicationReview(d)">中心审核</button><button v-if="role==='PUBLIC'&&d.state==='驳回待补'" class="primary" @click="form('补正申请材料',[f('reason','补充说明','textarea',{required:true}),attachment(true)],`/applications/${d.id}/supplement`)">补交材料</button></template>
   <template v-if="detail.type==='campaigns'"><button v-if="role==='GRID'" class="primary" @click="checkinForm(d)">宣传打卡</button></template><button v-if="detail.type==='articles'&&isCenter" @click="articleForm(d)">编辑文章</button>
   <button v-if="detail.type==='notices'&&!d.resolved" class="primary" @click="form('记录督办处理',[note('处理决定')],`/notices/${d.id}/resolve`)">处理督办</button><button v-if="detail.type==='corrections'&&isCenter&&d.state==='待审核'" class="primary" @click="form('审核回执更正',[f('approve','批准更正','checkbox'),note()],`/corrections/${d.id}/review`)">审核更正</button>
  </div>
  <div v-if="d.needs_review" class="warning-box">已有新线索归并，请完成补充复核。原有执行任务继续处理。</div><dl v-if="detailPairs.length" class="details-grid"><template v-for="pair in detailPairs"><dt>{{pair.label}}</dt><dd>{{pair.value}}</dd></template></dl>
  <div v-if="d.bank" class="info-box"><h4>模拟账户核查</h4><p>{{d.bank.holder}} · {{d.bank.account}}</p><p v-if="d.bank.available!=null">模拟可用余额 <strong>{{money(d.bank.available)}}</strong></p><small>本页执行只改变模拟账本。</small></div>
  <div v-for="(label,key) in {description:'情况说明',reason:'原因与说明',process_text:'现场过程',review_note:'复核意见',exception_note:'办结意见',note:'审核或处理意见',message:'提醒内容',resolution:'处理决定'}"><section v-if="d[key]" class="detail-section"><h3>{{label}}</h3><p class="pre-wrap">{{d[key]}}</p></section></div>
  <section v-if="d.body" class="article-body"><span class="tag">{{d.category}}</span><p>{{d.summary}}</p><div class="pre-wrap">{{d.body}}</div></section>
  <section v-if="d.progress" class="detail-section"><h3>当前办理进度</h3><span class="badge" :class="statusTone(d.progress.state)">{{d.progress.state}}</span></section>
  <section v-if="d.application" class="detail-section"><h3>关联申请 {{d.application.code}}</h3><p>{{d.application.reason}}</p><p>{{d.application.note}}</p><p v-if="d.application.payee">收款模拟账户 {{d.application.payee}}</p><div class="attachment-list"><a v-for="file in d.application.attachments" :href="'/api/attachments/'+file.id">▧ {{file.filename}} ↓</a></div></section>
  <section v-if="d.attachments?.length||d.reportMaterials?.length" class="detail-section"><h3>相关材料</h3><div class="attachment-list"><a v-for="file in [...(d.attachments||[]),...(d.reportMaterials||[])]" :key="file.id" :href="'/api/attachments/'+file.id">▧ {{file.filename}} ↓</a></div></section>
  <section v-if="d.reports" class="detail-section"><h3>关联原始线索</h3><article v-for="r in d.reports" class="clue-card"><header><strong>{{r.code}}</strong><span class="tag">{{r.source}}</span></header><p>{{r.kind}} · {{r.value}}</p><p>{{r.description}}</p><small>归一化 {{r.normalized}} · 金额 {{r.amount||'未提供'}} · 时刻 {{r.transactionTime||'未提供'}} · 异地 {{r.remote?'是':'否'}}</small><div class="attachment-list"><a v-for="file in r.attachments" :href="'/api/attachments/'+file.id">▧ {{file.filename}} ↓</a></div></article></section>
  <section v-if="d.scores?.length" class="detail-section"><h3>评分依据与版本</h3><details v-for="(score,i) in d.scores" class="score-record" :open="i===0"><summary><strong>{{score.score}} 分 · {{score.level}}风险</strong><span>线索 #{{score.report_id}} · 配置 v{{score.config_id}}</span></summary><table><thead><tr><th>因子</th><th>原始分</th><th>权重</th><th>加权贡献</th></tr></thead><tbody><tr v-for="factor in score.details.details"><td>{{factor.name}}</td><td>{{factor.factor}}</td><td>{{factor.weight}}%</td><td>{{factor.contribution}}</td></tr></tbody></table><p v-for="hit in score.details.matches" class="muted">匹配依据：{{hit.kind}} · {{hit.source}}</p><p v-if="score.details.fallback" class="warning-box">配置无效时已回退默认权重。</p><small>总分按非负数四舍五入；归并取关联线索最高总分。</small></details></section>
  <section v-if="d.receipts?.length" class="detail-section"><h3>回执记录</h3><article v-for="r in d.receipts" class="clue-card"><header><strong>版本 {{r.version}} · {{r.result}}</strong><span class="badge" :class="r.valid?'green':'gray'">{{r.valid?'当前有效':'历史版本'}}</span></header><p>实际金额 {{money(r.amount)}} · 凭证 {{r.voucher}}</p><p>{{r.reason}}</p><small>{{r.display_name}} · {{fmt(r.created_at)}}</small><div class="attachment-list"><a v-for="file in r.attachments" :href="'/api/attachments/'+file.id">▧ {{file.filename}} ↓</a></div></article></section>
  <section v-if="d.commands?.length" class="detail-section"><h3>关联指令</h3><button v-for="c in d.commands" class="linked-record" @click="openDetail('commands',c)"><span>{{c.code}} · {{c.kind}}</span><span class="badge" :class="statusTone(c.state)">{{c.state}}</span><span>→</span></button></section>
  <section v-if="d.visits?.length" class="detail-section"><h3>关联上门任务</h3><button v-for="v in d.visits" class="linked-record" @click="openDetail('visits',v)"><span>{{v.code}}</span><span class="badge" :class="statusTone(v.state)">{{v.state}}</span><span>→</span></button></section>
  <section v-if="d.records" class="detail-section"><h3>宣传活动记录</h3><article v-for="r in d.records" class="clue-card"><strong>{{r.form}} · {{r.sessions}}场 · {{r.people}}人次</strong><p>{{r.note}}</p><small>{{r.display_name}} · {{fmt(r.occurred_at)}}</small></article><p v-if="!d.records.length" class="muted">暂无打卡记录。</p></section>
  <section v-if="d.assessments?.length" class="detail-section"><h3>人工复核记录</h3><article v-for="r in d.assessments" class="clue-card"><strong>{{r.decision}} · {{r.display_name}}</strong><p>{{r.note}}</p><small>{{fmt(r.created_at)}}</small></article></section>
  <section v-if="d.timeline?.length" class="detail-section"><h3>办理时间线</h3><ol class="timeline"><li v-for="(t,i) in d.timeline" :key="i"><span class="timeline-dot"></span><time>{{fmt(t.created_at)}}</time><strong>{{t.action}} <span v-if="t.new_state">· {{t.new_state}}</span></strong><p v-if="t.note">{{t.note}}</p></li></ol></section>
 </div></section></div>
 <FormDialog v-if="modal" :key="modal.title" v-bind="modal" @close="modal=null" @done="done"/>
 <div v-if="receiptResult" class="modal-backdrop"><section class="dialog receipt-success" role="dialog" aria-modal="true" aria-label="受理成功"><span class="success-icon">✓</span><h2>举报已受理</h2><p>请保存以下信息，查询凭证只在本次提交后显示。</p><label>受理编号<input :value="receiptResult.code" readonly></label><label>查询凭证<input :value="receiptResult.queryToken" readonly></label><p v-if="receiptResult.processing" class="warning-box">线索已保存，将进入人工研判队列。</p><button class="primary" @click="queryCode=receiptResult.code;queryToken=receiptResult.queryToken;receiptResult=null;user?refresh():go('lookup')">我已保存</button></section></div>
 <div v-if="toast" class="toast" role="status"><span>✓</span>{{toast}}</div>
</template>
